INSERT INTO pacote_turistico (nome_pacote, destino, duracao, preco, data_inicio, data_fim, itinerario, descricao) VALUES
('Aventura na Patagônia', 'El Calafate, Argentina', '10 dias / 9 noites', 12500.00, '2026-05-20', '2026-05-30', 'Dia 1-3: El Calafate e Glaciar Perito Moreno. Dia 4-7: El Chaltén e trilhas. Dia 8-10: Ushuaia, o fim do mundo.', 'Explore as geleiras e montanhas da Patagônia em uma viagem inesquecível.'),
('Cultura e Cores do Japão', 'Tóquio e Kyoto, Japão', '12 dias / 11 noites', 22000.00, '2026-04-10', '2026-04-22', 'Dia 1-5: Exploração de Tóquio (Shibuya, Akihabara). Dia 6-10: Viagem para Kyoto (templos, gueixas). Dia 11-12: Retorno.', 'Uma imersão completa na cultura japonesa, dos templos antigos à metrópole futurista.'),
('Safári na Tanzânia', 'Serengeti, Tanzânia', '7 dias / 6 noites', 18500.00, '2026-07-15', '2026-07-22', 'Dia 1-2: Chegada em Arusha. Dia 3-6: Safári no Parque Nacional Serengeti. Dia 7: Retorno.', 'Testemunhe a grande migração e a vida selvagem africana em um safári de luxo.');
